// 1. Authentication Header Check (x-crown-apikey)
const headers = $input.item.json.headers || {};
const receivedApiKey = headers['x-crown-apikey'] || headers['X-Crown-ApiKey'] || '';
const expectedApiKey = 'crown_sec_live_9a7b3c2d1e4f5a6b7c8d9e0f1a2b3c4d5e';

if (!receivedApiKey || receivedApiKey !== expectedApiKey) {
  return [{
    json: {
      authenticated: false,
      error: 'Unauthorized: Invalid or missing API Key'
    }
  }];
}

return [{
  json: {
    authenticated: true,
    body: $input.item.json.body || {}
  }
}];

